<script lang="ts" setup>
import type { AiModelModelApi } from '#/api/ai/model/model';
import { onMounted, ref } from 'vue';
import { useRouter } from 'vue-router';
import { AiModelTypeEnum } from '@vben/constants';
import { message } from 'ant-design-vue';
import { getModelSimpleList, testModel } from '#/api/ai/model/model';
import { getPentPlatformSection, updatePentPlatformSection } from '#/api/pent';
const router=useRouter();const loading=ref(false);const saving=ref(false);const testing=ref<number>();const values=ref<Record<string,any>>({});const embeddingModels=ref<AiModelModelApi.Model[]>([]);const rerankModels=ref<AiModelModelApi.Model[]>([]);
const options=(rows:AiModelModelApi.Model[])=>rows.map(model=>({label:`${model.name} · ${model.platform} · ${model.model}`,value:model.id}));
async function load(){loading.value=true;try{const [config,embeddings,reranks]=await Promise.all([getPentPlatformSection('knowledge'),getModelSimpleList(AiModelTypeEnum.EMBEDDING),getModelSimpleList(AiModelTypeEnum.RERANK)]);values.value=config;embeddingModels.value=embeddings||[];rerankModels.value=reranks||[];if(!values.value.embedding_model_config_id&&embeddingModels.value[0])values.value.embedding_model_config_id=embeddingModels.value[0].id;if(!values.value.rerank_model_config_id&&rerankModels.value[0])values.value.rerank_model_config_id=rerankModels.value[0].id}catch(e:any){message.error(e?.message||'加载知识库设置失败')}finally{loading.value=false}}
async function test(id:number){if(!id)return;testing.value=id;try{const result=await testModel(id,'知识库连接测试');message.success(`连接成功，耗时 ${result.latencyMs}ms`)}catch(e:any){message.error(e?.message||'模型连接失败')}finally{testing.value=undefined}}
async function save(){if(!values.value.embedding_model_config_id){message.warning('请选择嵌入模型');return}saving.value=true;try{values.value=await updatePentPlatformSection('knowledge',values.value);message.success('知识库设置已保存')}catch(e:any){message.error(e?.message||'保存失败')}finally{saving.value=false}}
onMounted(load);
</script>
<template><a-spin :spinning="loading"><div class="heading"><div><h2>知识库设置</h2><p>配置知识检索、MultiQuery、精排、后处理与索引管线。</p></div><a-button type="primary" :loading="saving" @click="save">保存更改</a-button></div>
<section class="block"><h3>基础设置</h3><div class="switch-row"><div><b>启用知识检索功能</b><p>允许 Agent 从平台知识库召回上下文。</p></div><a-switch v-model:checked="values.enabled" /></div><a-form layout="vertical" class="base-path-form"><a-form-item label="知识库路径"><a-input v-model:value="values.base_path" placeholder="knowledge_base" /></a-form-item></a-form></section>
<section class="block"><div class="block-head"><div><h3>嵌入模型配置</h3><p>直接选择“AI 大模型”中已经配置的向量模型。</p></div><a-button @click="router.push('/ai/model')">管理 AI 大模型</a-button></div><a-form layout="vertical"><a-form-item label="嵌入模型" required><a-input-group compact><a-select v-model:value="values.embedding_model_config_id" :options="options(embeddingModels)" show-search option-filter-prop="label" placeholder="选择已配置的嵌入模型" style="width:calc(100% - 96px)"/><a-button :loading="testing===values.embedding_model_config_id" style="width:96px" @click="test(values.embedding_model_config_id)">测试连接</a-button></a-input-group></a-form-item></a-form></section>
<section class="block"><h3>检索配置</h3><a-row :gutter="20"><a-col :xs="24" :md="8"><a-form-item label="Top-K 结果数量"><a-input-number v-model:value="values.retrieval_top_k" :min="1" :max="20"/></a-form-item></a-col><a-col :xs="24" :md="8"><a-form-item label="相似度阈值"><a-input-number v-model:value="values.similarity_threshold" :min="0" :max="1" :step="0.05"/></a-form-item></a-col><a-col :xs="24" :md="8"><a-form-item label="子索引过滤"><a-input v-model:value="values.sub_index_filter" placeholder="例如 prod"/></a-form-item></a-col></a-row></section>
<section class="block"><h3>RAG 管线（MultiQuery + Rerank）</h3><p class="hint">LLM 多路改写检索 → 向量预取与融合 → 精排 → 去重和预算截断。</p><a-row :gutter="20"><a-col :xs="24" :md="8"><a-form-item label="MultiQuery 改写变体上限"><a-input-number v-model:value="values.multi_query_max_queries" :min="1" :max="8"/></a-form-item></a-col><a-col :xs="24" :md="16"><a-form-item label="精排模型"><a-input-group compact><a-select v-model:value="values.rerank_model_config_id" allow-clear :options="options(rerankModels)" placeholder="选择已配置的重排模型；留空则不启用精排" style="width:calc(100% - 96px)"/><a-button :disabled="!values.rerank_model_config_id" :loading="testing===values.rerank_model_config_id" style="width:96px" @click="test(values.rerank_model_config_id)">测试连接</a-button></a-input-group></a-form-item></a-col></a-row></section>
<section class="block"><h3>检索后处理（去重 / 预算）</h3><a-row :gutter="20"><a-col :xs="24" :md="8"><a-form-item label="向量预取候选数"><a-input-number v-model:value="values.prefetch_top_k" :min="0" :max="200"/></a-form-item></a-col><a-col :xs="24" :md="8"><a-form-item label="最大上下文字符数"><a-input-number v-model:value="values.max_context_chars" :min="0" :max="1000000"/></a-form-item></a-col><a-col :xs="24" :md="8"><a-form-item label="最大上下文 Token 数"><a-input-number v-model:value="values.max_context_tokens" :min="0" :max="1000000"/></a-form-item></a-col></a-row></section>
<section class="block"><h3>索引配置</h3><a-row :gutter="20"><a-col :xs="24" :md="8"><a-form-item label="分块策略"><a-select v-model:value="values.chunk_strategy" :options="[{label:'Markdown 标题 + 递归（推荐）',value:'markdown_then_recursive'},{label:'仅递归切分',value:'recursive'}]"/></a-form-item></a-col><a-col :xs="24" :md="8"><a-form-item label="嵌入 HTTP 超时（秒）"><a-input-number v-model:value="values.request_timeout_seconds" :min="0" :max="600"/></a-form-item></a-col><a-col :xs="24" :md="8"><a-form-item label="嵌入批大小"><a-input-number v-model:value="values.batch_size" :min="1" :max="256"/></a-form-item></a-col><a-col :xs="24" :md="8"><a-form-item label="分块大小（Token）"><a-input-number v-model:value="values.chunk_size" :min="128" :max="4096"/></a-form-item></a-col><a-col :xs="24" :md="8"><a-form-item label="分块重叠（Token）"><a-input-number v-model:value="values.chunk_overlap" :min="0" :max="512"/></a-form-item></a-col><a-col :xs="24" :md="8"><a-form-item label="单知识项最大块数"><a-input-number v-model:value="values.max_chunks_per_item" :min="0" :max="1000"/></a-form-item></a-col><a-col :xs="24" :md="8"><a-form-item label="每分钟最大请求数"><a-input-number v-model:value="values.max_rpm" :min="0" :max="1000"/></a-form-item></a-col><a-col :xs="24" :md="8"><a-form-item label="请求间隔（毫秒）"><a-input-number v-model:value="values.rate_limit_delay_ms" :min="0" :max="10000"/></a-form-item></a-col><a-col :xs="24" :md="8"><a-form-item label="最大重试次数"><a-input-number v-model:value="values.max_retries" :min="0" :max="10"/></a-form-item></a-col><a-col :xs="24" :md="8"><a-form-item label="重试间隔（毫秒）"><a-input-number v-model:value="values.retry_delay_ms" :min="0" :max="10000"/></a-form-item></a-col><a-col :xs="24" :md="8"><a-form-item label="优先读取磁盘源文件"><a-switch v-model:checked="values.prefer_source_file"/></a-form-item></a-col><a-col :xs="24" :md="8"><a-form-item label="Hermes 子索引"><a-input v-model:value="values.sub_indexes" placeholder="prod, knowledge"/></a-form-item></a-col></a-row></section></a-spin></template>
<style scoped>.heading,.block-head,.switch-row{display:flex;justify-content:space-between;align-items:flex-start;gap:20px}.heading{margin-bottom:22px}.heading h2{margin:0;font-size:24px}.heading p,.block-head p,.switch-row p,.hint{margin:6px 0 0;color:var(--ant-color-text-secondary)}.block{padding:22px 0;border-top:1px solid var(--ant-color-border-secondary)}.block h3{margin:0 0 18px;font-size:16px}.block-head{margin-bottom:18px}.block-head h3{margin-bottom:0}.block :deep(.ant-input-number){width:100%}.base-path-form{margin-top:20px;max-width:720px}.hint{margin:-10px 0 18px}</style>
